using System;using System.Data;using System.Data.SqlClient;using System.Drawing;using System.Windows.Forms;using AshkanJobCenter.Core;using AshkanJobCenter.Data;namespace AshkanJobCenter.UI{public class InterviewsPage:UserControl{DataGridView grid;public InterviewsPage(){BackColor=Theme.Background;Build();LoadData();}void Build(){var bar=new FlowLayoutPanel{Dock=DockStyle.Top,Height=55,Padding=new Padding(0,5,0,5)};var add=Ui.Button(L.Fa?"زمان‌بندی مصاحبه":"Schedule interview");add.Enabled=AppSession.Can("Applications.Manage");add.Click+=(s,e)=>Schedule();var refresh=Ui.Button(L.T("refresh"),false);refresh.Click+=(s,e)=>LoadData();bar.Controls.Add(add);bar.Controls.Add(refresh);Controls.Add(bar);grid=Ui.Grid();Controls.Add(grid);grid.BringToFront();}void LoadData(){grid.DataSource=Database.Query("SELECT i.Id,j.Title AS Job,c.FullName AS Candidate,i.ScheduledAt,i.InterviewType,i.Interviewer,i.Status,i.Location FROM Interviews i JOIN Applications a ON a.Id=i.ApplicationId JOIN Jobs j ON j.Id=a.JobId JOIN Candidates c ON c.Id=a.CandidateId ORDER BY i.ScheduledAt");}void Schedule(){var apps=Database.Query("SELECT a.Id, c.FullName+' - '+j.Title AS Caption FROM Applications a JOIN Jobs j ON j.Id=a.JobId JOIN Candidates c ON c.Id=a.CandidateId WHERE a.Stage<>'Rejected' ORDER BY a.Id DESC");if(apps.Rows.Count==0){MessageBox.Show(L.Fa?"درخواست فعالی وجود ندارد.":"No active applications.");return;}using(var d=new Form{Text=L.Fa?"مصاحبه جدید":"New interview",Size=new Size(480,420),StartPosition=FormStartPosition.CenterParent}){var lay=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(22),ColumnCount=1,RowCount=10};var cb=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,DisplayMember="Caption",ValueMember="Id",DataSource=apps,Dock=DockStyle.Top};var dt=new DateTimePicker{Format=DateTimePickerFormat.Custom,CustomFormat="yyyy/MM/dd HH:mm",Value=DateTime.Now.AddDays(1),Dock=DockStyle.Top};var type=Ui.Text();type.Text=L.Fa?"حضوری":"On-site";var interviewer=Ui.Text();var loc=Ui.Text();lay.Controls.Add(Ui.Label(L.Fa?"درخواست":"Application",10,true));lay.Controls.Add(cb);lay.Controls.Add(Ui.Label(L.Fa?"زمان":"Date & time",10,true));lay.Controls.Add(dt);lay.Controls.Add(Ui.Label(L.Fa?"نوع / مصاحبه‌کننده / محل":"Type / Interviewer / Location",10,true));lay.Controls.Add(type);lay.Controls.Add(interviewer);lay.Controls.Add(loc);var save=Ui.Button(L.T("save"));save.Click+=(s,e)=>{Database.Exec("INSERT Interviews(ApplicationId,ScheduledAt,InterviewType,Interviewer,Location) VALUES(@a,@d,@t,@i,@l)",new SqlParameter("@a",cb.SelectedValue),new SqlParameter("@d",dt.Value),new SqlParameter("@t",type.Text),new SqlParameter("@i",interviewer.Text),new SqlParameter("@l",loc.Text));Database.Audit("Schedule","Interview",cb.Text);d.DialogResult=DialogResult.OK;};lay.Controls.Add(save);d.Controls.Add(lay);Theme.Apply(d);if(d.ShowDialog(this)==DialogResult.OK)LoadData();}}}}